40:   const buildMarker = (position) => {
41:     const device = devices[position.deviceId];
42:     let showDirection;
43:     switch (directionType) {
44:       case 'none':
45:         showDirection = false;
46:         break;
47:       case 'all':
48:         showDirection = position.course > 0;
49:         break;
