55:       ? position.attributes.color || getStatusColor(device.status)
56:       : 'neutral';
57:     const titles = { name: device.name, fixTime: formatTime(position.fixTime, 'seconds') };
58:     return {
59:       id: position.id,
60:       deviceId: position.deviceId,
61:       latitude: position.latitude,
62:       longitude: position.longitude,
63:       image: `${mapIconKey(device.category)}-${color}`,
64:       title: titles[titleField || 'name'],
65:       rotation: position.course,
66:       direction: showDirection,
67:     };
68:   };
